#pragma once

#include "common/block_types.hpp"
#include "common/item_ids_gen.hpp"

// ItemID: one id space for everything an inventory slot can hold. Ids
// 0..LAST_BLOCK_ID-1 are block items (the same value as the BlockID);
// LAST_BLOCK_ID stays the empty-slot sentinel; pure items (data/items/*.json)
// live at ITEM_ID_BASE and above (see item_ids_gen.hpp, generated by
// tools/blocks_import.py).
typedef uint32_t ItemID;

// Maximum stack size for survival mode.
#define MAX_STACK_SIZE 64

// One rolled drop: an item plus a stack count.
typedef struct {
    ItemID item_id;
    int count;
} ItemStack;

static inline int item_is_block( ItemID id ) {
    return id < LAST_BLOCK_ID;
}

// A slot's id is usable: a defined block id below LAST_BLOCK_ID, or a defined
// pure-item id. LAST_BLOCK_ID itself is the empty sentinel, not a valid item.
static inline int item_id_valid( ItemID id ) {
    return item_is_block( id ) ? block_id_defined( id ) : item_id_defined( id );
}

typedef struct {
    TextureID icon_texture;
    unsigned char max_stack;
    // Tool classification for survival mining speed: the MineableClass this
    // item accelerates (MINEABLE_NONE = not a tool) and the multiplier it
    // mines at when the target block's mineable matches.
    unsigned char tool_class;
    // Health restored on eat, in half-hearts ("food" in data/items);
    // 0 = not edible.
    unsigned char food_heal;
    float mine_speed;
    // Block this item plants on farmland ("plants" in data/items);
    // LAST_BLOCK_ID when the item plants nothing.
    BlockID plant_block;
} ItemGenDef;

// The generated table lives in item.cpp (item_definitions_gen.inc) so
// regenerating it doesn't rebuild every TU that includes this header.
extern const ItemGenDef ITEM_DEFINITIONS[ ITEM_ID_END - ITEM_ID_BASE ];

// Stack limit per item: blocks are always MAX_STACK_SIZE; pure items come
// from the generated table (default 64, "max_stack" in data/items).
static inline int item_max_stack( ItemID id ) {
    if ( item_is_block( id ) ) {
        return MAX_STACK_SIZE;
    }
    return item_id_defined( id ) ? ITEM_DEFINITIONS[ id - ITEM_ID_BASE ].max_stack : MAX_STACK_SIZE;
}

// Below need block definitions — implemented in src/common/item.cpp.
TextureID item_icon_texture( ItemID id );
// Pure items always draw flat (non-isometric); blocks forward icon_is_isometric.
int item_icon_is_isometric( ItemID id );
const char *item_name( ItemID id );
// Case-insensitive name lookup over every defined block name plus the pure
// item names (REPGAME_ITEM_TEST / REPGAME_MOB_TEST held items).
// LAST_BLOCK_ID on no match.
ItemID item_id_from_name( const char *name );

// Per-tick mining-speed multiplier for survival block breaking: the item's
// mine_speed when its tool_class matches the block's mineable class, else 1.
float item_mining_speed( ItemID id, BlockID block_id );

// Hoe tools till suitable soil into farmland on right-click (see
// player_use_or_place_block); hoes carry tool_class MINEABLE_HOE.
static inline int item_is_hoe( ItemID id ) {
    return !item_is_block( id ) && item_id_defined( id ) && //
           ITEM_DEFINITIONS[ id - ITEM_ID_BASE ].tool_class == MINEABLE_HOE;
}

// The three bucket items: an empty BUCKET scoops a fluid source into
// WATER_BUCKET/LAVA_BUCKET; a filled bucket pours its fluid back out (see
// repgame_use_bucket).
static inline bool item_is_bucket( ItemID id ) {
    return id == BUCKET || id == WATER_BUCKET || id == LAVA_BUCKET;
}

// The fluid a filled bucket pours — LAST_BLOCK_ID for the empty bucket (and
// non-bucket items).
static inline BlockID item_bucket_fluid( ItemID id ) {
    return id == WATER_BUCKET ? WATER : id == LAVA_BUCKET ? LAVA : LAST_BLOCK_ID;
}

// The block a seed/produce item plants on farmland, LAST_BLOCK_ID for
// non-planting items.
static inline BlockID item_plant_block( ItemID id ) {
    return ( !item_is_block( id ) && item_id_defined( id ) ) ? //
               ITEM_DEFINITIONS[ id - ITEM_ID_BASE ].plant_block
                                                           : LAST_BLOCK_ID;
}

// Health an edible item restores on right-click eat, in half-hearts
// ("food" in data/items); 0 = not edible.
static inline int item_food_heal( ItemID id ) {
    return ( !item_is_block( id ) && item_id_defined( id ) ) ? //
               ITEM_DEFINITIONS[ id - ITEM_ID_BASE ].food_heal
                                                           : 0;
}

// The seed/produce item that plants a crop block, or LAST_BLOCK_ID when no
// item's plant chain reaches it. Pick-block uses this so any growth stage
// yields the planting item rather than the stage's block item. Implemented
// in item.cpp — needs block_definitions.hpp.
ItemID item_for_crop_block( BlockID id );

// Generated block drop table ("drops" in data/blocks/*.json). Blocks with no
// "drops" key are absent from BLOCK_DROP_TABLE and drop themselves.
typedef struct {
    ItemID item_id;
    int min;
    int max;
    float chance;
} BlockDropGen;

typedef struct {
    BlockID block_id;
    int offset;
    int count;
} BlockDropTableGen;

// Deterministic RNG for drop rolls: xorshift32, caller owns the state (never
// pass 0). Tests seed it directly; gameplay keeps a per-run state.
static inline uint32_t item_rng_next( uint32_t *state ) {
    uint32_t x = *state;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    *state = x;
    return x;
}

// Rolls a block's drop table into `out` (up to max_out entries) and returns
// the number written. A block with no "drops" key returns itself once;
// "drops": [] returns 0. Chance entries that fail their roll are skipped.
int block_roll_drops( BlockID id, uint32_t *rng_state, ItemStack *out, int max_out );
